    try {
        const { Parameter } = await client.send(new GetParameterCommand({ Name }));
        return Parameter?.Value;
    } catch (error) {
        if (error?.name === 'ParameterNotFound' || error?.Code === 'ParameterNotFound') {
            return undefined;
