import { getDocument } from '../../utils/aws/s3.js';
import { getParameterValue } from '../../utils/aws/awsSSM.js';
import { getInstanceTags } from '../../utils/aws/awsEc2.js';

const POOL_REFERENCE = 'pool/';
const UNIT_REFERENCE = 'unit/';
const ALIAS_REFERENCE = 'alias/';
const NODE_REFERENCE = 'node/';

/** Where a business' aliases are kept. One parameter per alias. */
const ALIAS_PARAMETER_PREFIX = '/paigo/attribution/alias/';

/** The tags an instance carries when finance has claimed it. */
const NODE_CHARGE_CODE_TAG = 'paigoChargeCode';
const NODE_ROLL_UP_TAG = 'paigoRollsInto';

/**
 * One step of an attribution chain. A step names the code it would book spend
 * to, and, when the owner passes the cost on to somebody else, the reference
 * the cost is passed to.
 */
export class AttributionLink {
    public chargeCode?: string;
    public passesTo?: string;
}

/**
 * One pocket of a business' estate. The finance system rewrites the whole set
 * whenever a team moves, so the pools are kept together in a single document
 * rather than one object each.
 */
export class AttributionPool {
    /** The code spend sitting on this pool is booked to. */
    public chargeCode: string;
    /** Set when the pool hands its cost on to another owner. */
    public rollsUpTo?: string;
}

export class AttributionPoolDocument {
    public revision: string;
    public pools: Record<string, AttributionPool>;
}

/**
 * A business unit. Each unit is its own object because the businesses that use
 * them edit one unit at a time.
 */
export class AttributionUnit {
    public unitId: string;
    /** The code spend sitting on this unit is booked to. */
    public chargeCode: string;
    /** Set when the unit hands its cost on to another owner. */
    public parentRef?: string;
}

/**
 * The attribution material a business keeps beside its onboarding record.
 *
 * A reference a usage line carries is only the start of the story: pools,
 * units, aliases and tagged instances may each pass the cost they receive on
 * to another owner. The directory walks that chain so spend lands on the code
 * that ultimately carries it rather than on the first code it meets.
 */
export class AttributionDirectory {
    private readonly pools: Record<string, AttributionPool>;

    private readonly bucket: string;

    private readonly prefix: string;

    /** Credentials for reading an account a node reference points into. */
    private readonly credentialsForAccount: (accountId: string) => unknown;

    /** Every step already read, so a shared owner is only fetched once. */
    private readonly links: Record<string, Promise<AttributionLink>> = {};

    /** Every reference already walked, keyed by the reference walked from. */
    private readonly resolved: Record<string, Promise<string>> = {};

    private constructor(
        pools: Record<string, AttributionPool>,
        bucket: string,
        prefix: string,
        credentialsForAccount: (accountId: string) => unknown,
    ) {
        this.pools = pools;
        this.bucket = bucket;
        this.prefix = prefix;
        this.credentialsForAccount = credentialsForAccount;
    }

    static async load(
        bucket: string,
        prefix: string,
        credentialsForAccount: (accountId: string) => unknown = () => undefined,
    ): Promise<AttributionDirectory> {
        const document = await getDocument<AttributionPoolDocument>(bucket, `${prefix}pools.json`);
        return new AttributionDirectory(document?.pools ?? {}, bucket, prefix, credentialsForAccount);
    }

    /**
     * The charge code that ultimately carries the spend of a usage line, found
     * by following the line's reference through every owner that passes the
     * cost on. A chain that loops back on itself is booked to the code its
     * members share.
     */
    async chargeCodeFor(reference: string): Promise<string> {
        if (!reference) {
            return undefined;
        }
        if (!(reference in this.resolved)) {
            this.resolved[reference] = this.walk(reference);
        }
        return this.resolved[reference];
    }

    /**
     * Follows a reference to the end of its chain.
     */
    private async walk(reference: string): Promise<string> {
        const visited: Array<AttributionLink> = [];
        const seen: Record<string, number> = {};
        let current = reference;

        while (current) {
            if (current in seen) {
                // The chain repeats: everything from the first sighting of this
                // reference onwards is the cycle itself.
                return AttributionDirectory.sharedChargeCode(visited.slice(seen[current]));
            }
            seen[current] = visited.length;
            // Each step has to be read before the next one is known.
            // eslint-disable-next-line no-await-in-loop
            const link = await this.linkFor(current);
            if (!link) {
                break;
            }
            visited.push(link);
            if (!link.passesTo) {
                break;
            }
            current = link.passesTo;
        }

        // The last owner that named a code carries the spend. Anything further
        // along the chain either named no code of its own, such as an alias, or
        // could not be read at all.
        return AttributionDirectory.lastChargeCode(visited);
    }

    /**
     * The single step a reference names, whichever kind of reference it is.
     */
    private async linkFor(reference: string): Promise<AttributionLink> {
        if (!(reference in this.links)) {
            this.links[reference] = this.readLink(reference);
        }
        return this.links[reference];
    }

    private async readLink(reference: string): Promise<AttributionLink> {
        if (reference.startsWith(POOL_REFERENCE)) {
            const pool = this.pools[reference.slice(POOL_REFERENCE.length)];
            return pool ? { chargeCode: pool.chargeCode, passesTo: pool.rollsUpTo } : undefined;
        }
        if (reference.startsWith(UNIT_REFERENCE)) {
            const unit = await this.readUnit(reference.slice(UNIT_REFERENCE.length));
            return unit ? { chargeCode: unit.chargeCode, passesTo: unit.parentRef } : undefined;
        }
        if (reference.startsWith(ALIAS_REFERENCE)) {
            const target = await getParameterValue(`${ALIAS_PARAMETER_PREFIX}${reference.slice(ALIAS_REFERENCE.length)}`);
            // An alias only points somewhere, it never carries spend itself.
            return target ? { passesTo: target } : undefined;
        }
        if (reference.startsWith(NODE_REFERENCE)) {
            return this.readNode(reference.slice(NODE_REFERENCE.length));
        }
        return undefined;
    }

    private async readUnit(name: string): Promise<AttributionUnit> {
        try {
            return await getDocument<AttributionUnit>(this.bucket, `${this.prefix}units/${name}.json`);
        } catch (error) {
            return undefined;
        }
    }

    /**
     * A node reference names an instance in one of the business' accounts, in
     * the form `<accountId>/<region>/<instanceId>`. Finance claims an instance
     * by tagging it.
     */
    private async readNode(path: string): Promise<AttributionLink> {
        const [accountId, region, instanceId] = path.split('/');
        if (!accountId || !region || !instanceId) {
            return undefined;
        }
        const tags = await getInstanceTags(region, this.credentialsForAccount(accountId), instanceId);
        if (!tags) {
            return undefined;
        }
        const chargeCode = tags[NODE_CHARGE_CODE_TAG];
        const passesTo = tags[NODE_ROLL_UP_TAG];
        if (!chargeCode && !passesTo) {
            return undefined;
        }
        return { chargeCode, passesTo };
    }

    /**
     * The code a cycle books to. Owners that pass cost round in a circle are
     * expected to name the same code; when they disagree the code the most of
     * them name wins, so the same cycle always books to the same place.
     */
    private static sharedChargeCode(cycle: Array<AttributionLink>): string {
        const counts: Record<string, number> = {};
        cycle.forEach(({ chargeCode }) => {
            if (chargeCode) {
                counts[chargeCode] = (counts[chargeCode] ?? 0) + 1;
            }
        });
        const codes = Object.keys(counts).sort();
        if (!codes.length) {
            return undefined;
        }
        return codes.reduce((best, code) => (counts[code] > counts[best] ? code : best), codes[0]);
    }

    private static lastChargeCode(visited: Array<AttributionLink>): string {
        for (let index = visited.length - 1; index >= 0; index -= 1) {
            if (visited[index].chargeCode) {
                return visited[index].chargeCode;
            }
        }
        return undefined;
    }
}
