            roleArn: 'arn:aws:iam::111111111111:role/paigo-metering',
            region: 'us-east-1',
            usageBucket: 'paigo-usage-example-one',
        },
        {
            accountId: '222222222222',
            roleArn: 'arn:aws:iam::222222222222:role/paigo-metering',
            region: 'us-east-1',
            usageBucket: 'paigo-usage-example-two',
        },
    ],
};

const pools = {
    // Keeps its own spend.
    aurora: { chargeCode: 'cc-platform-core' },
    // Passes its spend down a chain of every other kind of owner.
    brindle: { chargeCode: 'cc-blob-gc', rollsUpTo: 'alias/westmoor' },
    // Two owners that pass the cost to each other.
    mossgate: { chargeCode: 'cc-batch-scoring', rollsUpTo: 'unit/northgate' },
};

const units = {
    coppice: { unitId: 'bu-coppice', chargeCode: 'cc-price-feed', parentRef: 'node/222222222222/eu-west-1/i-abc' },
    fernlea: { unitId: 'bu-fernlea', chargeCode: 'cc-observability' },
    northgate: { unitId: 'bu-northgate', chargeCode: 'cc-batch-scoring', parentRef: 'pool/mossgate' },
};

const batches = {
    'paigo-usage-example-one/usage/111111111111/first.json': {
        batchId: 'first',
        coveringDate: '2026-01-01',
        lines: [
            { lineId: 'ln-1', quantity: 10, amount: 1.5, attribution: 'pool/aurora' },
            { lineId: 'ln-2', quantity: 20, amount: 2.5, attribution: 'pool/brindle' },
        ],
    },
    'paigo-usage-example-one/usage/111111111111/second.json': {
        batchId: 'second',
        coveringDate: '2026-02-02',
        lines: [{ lineId: 'ln-3', quantity: 5, amount: 0.5, attribution: 'pool/mossgate' }],
    },
    'paigo-usage-example-two/usage/222222222222/first.json': {
        batchId: 'first',
        coveringDate: '2026-01-01',
        lines: [
            { lineId: 'ln-4', quantity: 1, amount: 0.25, attribution: 'pool/brindle' },
            { lineId: 'ln-5', quantity: 2, amount: 0.75, attribution: 'pool/aurora' },
            { lineId: 'ln-6', quantity: 3, amount: 1.25, attribution: 'pool/unknown' },
        ],
    },
};

describe('UsageAttributionService', () => {
    beforeEach(() => {
        jest.clearAllMocks();
        (getDocument as jest.Mock).mockImplementation(async (bucket: string, key: string) => {
            if (key === 'onboarding/registry.json') {
                return registry;
            }
            if (key === 'attribution/pools.json') {
                return { revision: '1', pools };
            }
            if (key.startsWith('attribution/units/')) {
                const unit = units[key.replace('attribution/units/', '').replace('.json', '')];
                if (!unit) {
                    throw new Error('NoSuchKey');
                }
                return unit;
            }
            return batches[`${bucket}/${key}`];
        });
        (listDocumentKeys as jest.Mock).mockImplementation(async (bucket: string, prefix: string) =>
            Object.keys(batches)
                .filter((key) => key.startsWith(`${bucket}/${prefix}`))
                .map((key) => key.slice(`${bucket}/`.length)),
        );
        (getParameterValue as jest.Mock).mockImplementation(async (name: string) =>
            name === '/paigo/attribution/alias/westmoor' ? 'unit/coppice' : undefined,
        );
        (getInstanceTags as jest.Mock).mockImplementation(async (region: string, credentials, instanceId: string) =>
            region === 'eu-west-1' && instanceId === 'i-abc'
                ? { paigoChargeCode: 'cc-consent-svc', paigoRollsInto: 'unit/fernlea' }
                : undefined,
        );
    });

    it('reports one row for every code that ultimately carries spend', async () => {
        const service = new UsageAttributionService(undefined);
        const rows = await service.attributeSpend({
            businessID: 'biz-example',
            registryBucket: REGISTRY_BUCKET,
            registryKey: 'onboarding/registry.json',
        });

        expect(rows).toEqual([
            { businessID: 'biz-example', chargeCode: 'cc-batch-scoring', quantity: 5, amount: 0.5, lineCount: 1 },
            { businessID: 'biz-example', chargeCode: 'cc-observability', quantity: 21, amount: 2.75, lineCount: 2 },
            { businessID: 'biz-example', chargeCode: 'cc-platform-core', quantity: 12, amount: 2.25, lineCount: 2 },
        ]);
    });

    it('never books spend to a code that only passes the cost on', async () => {
        const service = new UsageAttributionService(undefined);
        const rows = await service.attributeSpend({
            businessID: 'biz-example',
            registryBucket: REGISTRY_BUCKET,
            registryKey: 'onboarding/registry.json',
        });

        const codes = rows.map(({ chargeCode }) => chargeCode);
        expect(codes).not.toContain('cc-blob-gc');
        expect(codes).not.toContain('cc-price-feed');
        expect(codes).not.toContain('cc-consent-svc');
        // Every line that names material we hold is counted exactly once.
        expect(rows.reduce((total, { lineCount }) => total + lineCount, 0)).toEqual(5);
    });

    it('reads the accounts named by the onboarding record with their own role', async () => {
        const service = new UsageAttributionService(undefined);
        await service.attributeSpend({
            businessID: 'biz-example',
            registryBucket: REGISTRY_BUCKET,
            registryKey: 'onboarding/registry.json',
        });

        expect((listDocumentKeys as jest.Mock).mock.calls).toEqual([
            ['paigo-usage-example-one', 'usage/111111111111/', { roleArn: registry.accounts[0].roleArn }],
            ['paigo-usage-example-two', 'usage/222222222222/', { roleArn: registry.accounts[1].roleArn }],
        ]);
        // The instance a node reference names sits in the second account, so it
        // has to be read with that account's role rather than our own.
        expect((getInstanceTags as jest.Mock).mock.calls[0]).toEqual([
            'eu-west-1',
            { roleArn: registry.accounts[1].roleArn },
            'i-abc',
        ]);
    });
});
