    /**
     * Reads every usage export the business' accounts have written and returns
     * one row per charge code that ultimately carries the exported lines, after
     * following every owner that passes the cost it receives on to somebody
     * else. Each line lands under exactly one final code.
     */
    async attributeSpend({
        businessID,
        registryBucket,
        registryKey,
    }: {
        businessID: string;
        registryBucket: string;
        registryKey: string;
    }): Promise<Array<AttributedSpendEntity>> {
        const registry = await MeteringRegistry.load(registryBucket, registryKey);
        const accountsById = (registry.accounts ?? []).reduce(
            (acc, account) => {
                acc[account.accountId] = account;
                return acc;
            },
            {} as Record<string, MeteredAccount>,
        );
        const directory = await AttributionDirectory.load(registryBucket, registry.attributionPrefix, (accountId) =>
            accountsById[accountId] ? credentialsForAccount(accountsById[accountId]) : undefined,
        );
        const totals: Record<string, AttributedSpendEntity> = {};

        for (const account of registry.accounts) {
            // eslint-disable-next-line no-await-in-loop
            const lines = await UsageExport.linesForAccount(
                account.usageBucket,
                registry.usageExportPrefix,
                account.accountId,
                credentialsForAccount(account),
            );
            // The chain a line's reference starts has to be walked before the
            // line can be booked, and every step of it is cached, so the lines
            // are taken one at a time.
            for (const line of lines) {
                // eslint-disable-next-line no-await-in-loop
                const chargeCode = await directory.chargeCodeFor(line.attribution);
                if (chargeCode) {
                    const running =
                        totals[chargeCode] ??
                        new AttributedSpendEntity({ businessID, chargeCode, quantity: 0, amount: 0, lineCount: 0 });
                    running.quantity += Number(line.quantity ?? 0);
                    running.amount += Number(line.amount ?? 0);
                    running.lineCount += 1;
                    totals[chargeCode] = running;
                }
            }
        }

        const codes = Object.keys(totals).sort();
        UsageAttributionService.logger.log(
            `Attributed spend across ${codes.length} charge codes for ${registry.accounts.length} accounts`,
        );
        return codes.map((code) => totals[code]);
